# פרק 13 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=13
TITLE='רשלנות רפואית'
SUM=[' <p>יישום עוולת הרשלנות בהקשר הרפואי, בשילוב <strong>חוק זכויות החולה, התשנ"ו–1996</strong>.</p> <h3>13.1 סטנדרט הרופא הסביר</h3> <p>הרופא נמדד לפי <strong>רופא סביר וכשיר באותו תחום</strong>, בהתאם לפרקטיקה הרפואית המקובלת בעת הטיפול. סטייה ממנה (באבחון, בטיפול, במעקב) — התרשלות.</p> <h3>13.2 הסכמה מדעת — סעיף 13 לחוק זכויות החולה</h3> <p>אין לתת טיפול אלא ב<strong>הסכמה מדעת</strong> — לאחר מסירת המידע הדרוש ל"מטופל הסביר" (מהות הטיפול, סיכונים, חלופות, סיכויים). לטיפולים מסוימים נדרשת הסכמה בכתב (<strong>סעיף 14</strong>).</p> <h3>13.3 פגיעה באוטונומיה — הלכת דעקה</h3> <p>ב<strong>דעקה נ\' בית החולים כרמל</strong> הוכרה <strong>פגיעה באוטונומיה</strong> כראש נזק עצמאי (לא-ממוני): עצם שלילת זכות ההחלטה מהמטופל מזכה בפיצוי — גם אם הטיפול עצמו לא היה רשלני וגם בלא קשר סיבתי לנזק הגופני.</p> <h3>13.4 נקודות מפתח למבחן</h3> <ul><li>סטנדרט הרופא הסביר לפי הפרקטיקה המקובלת.</li><li>הסכמה מדעת (ס׳ 13 לחוק זכויות החולה).</li><li>פגיעה באוטונומיה כראש נזק עצמאי (דעקה).</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('חוק זכויות החולה, התשנ"ו-1996 (ס׳ 13)', '', 'איסור מתן טיפול ללא הסכמה מדעת; חובת מסירת מידע מהותי למטופל הסביר; לטיפולים מסוימים נדרשת הסכמה בכתב (ס׳ 14).'), ('ע"א 2781/93 דעקה נ\' בית החולים כרמל', '', 'הכרה בפגיעה באוטונומיה כראש נזק עצמאי — שלילת זכות ההחלטה מזכה בפיצוי גם בלא קשר סיבתי לנזק הגופני.'), ('סטנדרט הרופא הסביר', '', 'הרשלנות הרפואית נבחנת לפי רופא סביר וכשיר באותו תחום ולפי הפרקטיקה הרפואית המקובלת בעת הטיפול.'), ('דנ״א 7794/98 רביד נ׳ קליפורד, פ״ד נז(4) 721', 'ילדה התמוטטה בטיפול שיניים ונגרם לה נזק מוחי קשה לאחר זריקת הרדמה במזרק שאינו שואב. השימוש במזרק כזה היה אז פרקטיקה מקובלת. הסוגיה הוכרעה בדיון נוסף בבית המשפט העליון (2003).', 'נקבע שעמידה בפרקטיקה מקובלת יוצרת לכל היותר חזקה הניתנת לסתירה שלא הייתה התרשלות, ואינה הגנה הרמטית. החזקה נסתרה, כי הסיכון היה ידוע, והמזרק השואב היה זמין, פשוט וזול. בית המשפט מוסמך לקבוע שהפרקטיקה עצמה רשלנית.'), ('ע״א 4384/90 ואתורי נ׳ בית החולים לניאדו, פ״ד נא(2) 171', 'דיון בתביעה בגין טיפול רפואי שניתן בלי שנמסר למטופלת המידע הדרוש להסכמה מדעת, ובשאלת הקשר הסיבתי בין אי־הגילוי לבין הנזק.', 'בתביעה על אי־גילוי שגרם לנזק גוף, התובע צריך להראות שאילו קיבל מידע מלא היה נמנע מהטיפול. בית המשפט מכריע בכך על דרך אומדן, לפי התנהגותו של חולה סביר בנסיבות התובע, ולא רק לפי עדות התובע בדיעבד. בפסק הדין נדונה גם האפשרות של הכרעה יחסית לפי סיכויים.'), ('ע״א 2781/93 דעקה נ׳ בית החולים כרמל, פ״ד נג(4) 526', 'מטופלת שהגיעה לניתוח ברגל הוחתמה, כשכבר הייתה בחדר הניתוח ומטושטשת מתרופות, על הסכמה לפעולה בכתף. בהמשך נגרם לה נזק בכתף.', 'הרופאים התרשלו בכך שלא קיבלו הסכמה מדעת. עם זאת, לא הוכח שהייתה מסרבת אילו קיבלה מידע, ולכן לא נפסק פיצוי על נזק הגוף. הוכרה פגיעה באוטונומיה ובכבוד כנזק לא ממוני בר פיצוי, בלי צורך בקשר סיבתי לנזק הגוף.'), ('ע״א 1303/09 קדוש נ׳ בית החולים ביקור חולים', 'ערעור בשאלת חובת הגילוי והפיצוי בגין טיפול רפואי שניתן בלי שנמסר למטופלת מידע מהותי (פסק הדין ניתן ב־2012).', 'העליון ביסס את הפגיעה באוטונומיה כראש נזק עצמאי ועסק בשיקולים לקביעת גובהו: מהות המידע שלא נמסר ומידת חשיבותו, חומרת הפגיעה בזכות הבחירה ועוצמת התחושות השליליות. הפיצוי אינו אמור להיות סמלי.'), ('דנ״א 4693/05 בית חולים כרמל חיפה נ׳ מלול, פ״ד סד(1) 533', 'נטען שבית החולים איחר בביצוע ניתוח קיסרי בלידה מוקדמת, והתינוקת נולדה עם שיתוק מוחין. לא ניתן היה לדעת אם הנזק נגרם מהאיחור או מהפגות. בערעור (ע״א 7375/02) נפסק פיצוי יחסי של 20%.', 'בדיון הנוסף, בהרכב של תשעה, העמדה שנתפסה כדעת הרוב (ריבלין) הגבילה פיצוי לפי הסתברות בהגברת סיכון בעיקר למקרים של "הטיה נשנית": מזיק, קבוצת ניזוקים, סיכון חוזר ומשותף והטיה עקבית של כלל מאזן ההסתברויות. במקרה היחידני לא הוכחה הטיה כזו. הלכת פאתח בדבר אובדן סיכויי החלמה נותרה בתוקפה.'), ('ע״א 231/84 קופת חולים של ההסתדרות נ׳ פאתח, פ״ד מב(3) 312', 'תביעה בשל התרשלות באבחון ובטיפול, שהפחיתה את סיכויי ההחלמה של המטופל.', 'לראשונה הוכרה האפשרות לפסוק פיצוי יחסי על אובדן סיכויי החלמה, בשיעור הסיכוי שאבד בגלל הרשלנות, גם כשלא ניתן להוכיח במאזן הסתברויות שהרשלנות גרמה לתוצאה הסופית. ההלכה חלה גם על מקרים יחידניים.'), ('ע״א 1326/07 המר נ׳ עמית', 'ערעורים שעסקו בתביעות של ילדים שנולדו עם מומים בשל רשלנות באבחון בהריון, ושל הוריהם (פסק הדין ניתן ב־2012).', 'בוטלה עילת "חיים בעוולה" של הילד, כי לא ניתן להשוות חיים עם מום לאי־היוולדות ולראות בהם נזק. במקביל הורחבה תביעת ההורים בעילת הולדה בעוולה, כך שתכלול את מלוא צורכי הילד גם לאחר בגירותו ולכל תוחלת חייו. נקבעו הוראות מעבר בעניין התיישנות.')]
QS=[{'q': 'מהו אמת המידה לבחינת התרשלותו של רופא לפי ס׳ 35 לפקודת הנזיקין?', 'o': ['מה שהמטופל ציפה לו באופן סובייקטיבי', 'בעל מקצוע סביר וכשיר באותו משלח יד, בזמן הטיפול', 'האדם הסביר מן השורה', 'הרופא המומחה הטוב ביותר בתחום'], 'c': 1, 'e': 'נכון. רופא נבחן מול "אדם סביר ונבון וכשיר לפעול באותו משלח יד", לפי מה שהיה ידוע ומקובל בעת הטיפול.'}, {'q': 'מה קבע בית המשפט העליון ברביד נ׳ קליפורד בעניין פרקטיקה רפואית מקובלת?', 'o': ['עמידה בפרקטיקה מקובלת היא הגנה מוחלטת מפני רשלנות', 'רק פרקטיקה שאושרה בחוזר משרד הבריאות מגינה על הרופא', 'עמידה בפרקטיקה יוצרת חזקה הניתנת לסתירה שלא הייתה התרשלות', 'פרקטיקה מקובלת אינה רלוונטית כלל לשאלת הרשלנות'], 'c': 2, 'e': 'נכון. הפרקטיקה יוצרת חזקה, וזו נסתרה במקרה, כי הסיכון היה ידוע ואמצעי הזהירות היה זמין וזול.'}, {'q': 'מתמחה בשנתו הראשונה ביצע פעולה רפואית בצורה שרופא מנוסה לא היה מבצע, ונגרם נזק. איזה סטנדרט יחול עליו?', 'o': ['סטנדרט של סטודנט לרפואה', 'סטנדרט של רופא סביר באותו תחום, ללא הנחה', 'סטנדרט מקל של מתמחה, כי הוא נמצא בהכשרה', 'אין עליו אחריות כלל, רק על הרופא הבכיר שמעליו'], 'c': 1, 'e': 'נכון. מתמחה נבחן כרופא סביר. האינטרס בטיפול איכותי גובר על האינטרס להקל עם הלומד.'}, {'q': 'מה קובע ס׳ 13(ב) לחוק זכויות החולה לגבי היקף המידע שיש למסור לשם הסכמה מדעת?', 'o': ['רק מידע שהמטופל ביקש במפורש', 'מידע רפואי הדרוש באורח סביר להחלטה, לרבות אבחנה, סיכונים, וסיכויים וסיכונים של חלופות ושל היעדר טיפול', 'מידע לפי שיקול דעתו הבלעדי של הרופא, כפי שנהוג במחלקה', 'רק את הסיכונים שבטיפול המוצע'], 'c': 1, 'e': 'נכון. זו לשון הסעיף. הרשימה פתוחה ("לרבות") וכוללת חמש קטגוריות, ובהן חלופות והיעדר טיפול.'}, {'q': 'אישה עברה ניתוח בלי שהוסבר לה סיכון מהותי. בית המשפט שוכנע שגם לו הוסבר לה, הייתה מסכימה לניתוח. הסיכון התממש. מה הדין?', 'o': ['היא זכאית לפיצוי מלא על נזק הגוף', 'היא זכאית לפיצוי רק אם הניתוח בוצע ברשלנות', 'אין לה כל פיצוי, כי לא הוכח קשר סיבתי', 'היא אינה זכאית לפיצוי על נזק הגוף, אך זכאית לפיצוי על פגיעה באוטונומיה'], 'c': 3, 'e': 'נכון. זו הלכת דעקה: נזק הגוף אינו מפוצה בלי קשר סיבתי, אבל שלילת הבחירה עצמה היא נזק לא ממוני עצמאי.'}, {'q': 'לפי הלכת ואתורי, כיצד מכריע בית המשפט אם מטופל היה מסרב לטיפול אילו קיבל מידע מלא?', 'o': ['לפי מה שרוב הרופאים היו ממליצים', 'על דרך אומדן, לפי התנהגותו של חולה סביר בנסיבות התובע', 'לפי עדות המטופל בלבד, כי רק הוא יודע מה היה עושה', 'לעולם מניחים שהיה מסרב, ולכן הנטל על הרופא'], 'c': 1, 'e': 'נכון. בית המשפט מעריך כיצד היה נוהג חולה סביר בנסיבותיו של התובע, בשילוב נתוניו האישיים.'}, {'q': 'מה ההבדל המרכזי בין הלכת פאתח לבין דנ״א מלול?', 'o': ['פאתח שללה פיצוי יחסי, ומלול הכירה בו לראשונה', 'פאתח הכירה בפיצוי יחסי על אובדן סיכויי החלמה גם במקרה יחידני, ומלול הגבילה פיצוי הסתברותי בהגברת סיכון בעיקר למקרים של הטיה נשנית', 'שתיהן עוסקות רק בנזקי רכוש', 'מלול ביטלה את הלכת פאתח'], 'c': 1, 'e': 'נכון. הלכת פאתח בדבר פגיעה בסיכוי נותרה על כנה, ואילו בהגברת סיכון דרשה דעת הרוב במלול "הטיה נשנית".'}, {'q': 'בשל איחור רשלני באבחון ירד סיכוי ההחלמה של מטופל מ־80% ל־60%, והוא לא החלים. לפי הנוסחה שאומצה בפסיקה, מה החלק שיש לייחס לנתבע?', 'o': ['100%', '50%', '25%', '20%'], 'c': 1, 'e': 'נכון. סיכון אי־ההחלמה עלה מ־20% (a) ל־40% (b), ולכן החלק הוא (b−a)/b = 20/40 = 50%.'}, {'q': 'בית חולים לא ביצע בדיקה שנדרשה וגם לא תיעד את מצב המטופל בשעות קריטיות. כתוצאה מכך התובע אינו יכול להוכיח מה גרם לנזק. מה הכלל הרלוונטי?', 'o': ['התביעה נדחית, כי הנטל על התובע', 'הנטל לגבי העובדות שתיעוד תקין היה מבהיר עובר לנתבע (רשומה חסרה ונזק ראייתי)', 'בית המשפט פוסק אוטומטית פיצוי מלא', 'יש לפנות לוועדת בדיקה לפי חוק זכויות החולה, ואין עילה נזיקית'], 'c': 1, 'e': 'נכון. היעדר רשומה (ס׳ 17) ודוקטרינת הנזק הראייתי מעבירים לנתבע את נטל השכנוע בפלוגתא הרלוונטית.'}, {'q': 'חולה נדבק בזיהום חמור במהלך אשפוז, ואינו יודע כיצד נדבק. איזה כלי עשוי לעזור לו?', 'o': ['ס׳ 41 לפקודה (הדבר מעיד על עצמו), שהוחל גם על זיהום שנרכש בבית חולים', 'ס׳ 38 לפקודה (דברים מסוכנים), שחל על כל חיידק', 'אחריות מוחלטת לפי חוק זכויות החולה', 'אין כלי, כי חיידק אינו "נכס"'], 'c': 0, 'e': 'נכון. ברז נ׳ אלישע נקבע שמתקני בית החולים כולם הם "נכס" שבשליטתו, ורק בידיו ההסבר. לכן ס׳ 41 חל.'}, {'q': 'הריונית לא קיבלה מידע על בדיקה גנטית חדשנית שזמינה רק באופן פרטי. התגלה שהעובר נושא את התסמונת שהבדיקה מאתרת. מה ההלכה?', 'o': ['חובת הגילוי מוטלת על המטופלת לברר בעצמה', 'אין חובה לגלות בדיקות שאינן בסל הבריאות', 'חובת הגילוי עשויה לכלול גם בדיקות חדשניות שמוכרות בפרקטיקה וזמינות באופן פרטי', 'חובת הגילוי חלה רק על בדיקות שהוכח שהן זולות'], 'c': 2, 'e': 'נכון. כך נקבע בע״א 2124/12 שירותי בריאות כללית נ׳ פלונית (2014), בעניין בדיקת X שביר.'}, {'q': 'מה קבע בית המשפט העליון בע״א 1326/07 המר נ׳ עמית?', 'o': ['ביטל את עילת "חיים בעוולה" של הילד והרחיב את תביעת ההורים בהולדה בעוולה לכל חיי הילד', 'קבע שמומים מולדים אינם נזק כלל, ולכן אין פיצוי', 'הכיר לראשונה בעילת "חיים בעוולה"', 'ביטל גם את תביעת ההורים'], 'c': 0, 'e': 'נכון. עילת הילד בוטלה, ותביעת ההורים הורחבה לצורכי הילד גם לאחר בגירותו ולכל תוחלת חייו.'}, {'q': 'רופא בחר בין שתי שיטות טיפול מקובלות שלכל אחת תומכים בספרות. השיטה שבחר התבררה בדיעבד כפחות טובה למטופל. האם התרשל?', 'o': ['כן, תמיד יש לבחור בשיטה החדשה יותר', 'כן, כי התוצאה מוכיחה שבחר לא נכון', 'לא, בחירה סבירה בין אסכולות מקובלות אינה התרשלות, גם אם בדיעבד הייתה עדיפה האחרת', 'רק אם המטופל לא חתם על טופס'], 'c': 2, 'e': 'נכון. הפסיקה מגינה על בחירה סבירה בין אסכולות. שאלה נפרדת היא אם הוצגו למטופל החלופות.'}, {'q': 'מטופל נכנס לניתוח תוספתן. במהלך הניתוח החליט המנתח, בלי צורך דחוף, להסיר גם ציסטה בשחלה שלא היה עליה דיבור. מה הסיווג הנכון?', 'o': ['מותר לפי ס׳ 15(3) כמצב חירום', 'טיפול שלא ניתנה לו כל הסכמה, שעשוי להוות תקיפה וגם הפרת חובת הגילוי והפגיעה באוטונומיה', 'רשלנות רגילה בלבד, כי הניתוח הצליח', 'אין עוולה כל עוד לא נגרם נזק גופני'], 'c': 1, 'e': 'נכון. פעולה בלי שום הסכמה קרובה לתקיפה (שיעור 8), ובכל מקרה מקימה פיצוי על פגיעה באוטונומיה.'}, {'q': 'לפי ס׳ 14 לחוק זכויות החולה, באיזו צורה ניתנת הסכמה מדעת?', 'o': ['רק בפני שני עדים', 'בכתב, בעל פה או בדרך של התנהגות, ולטיפולים שבתוספת הראשונה נדרש מסמך בכתב', 'תמיד בכתב בלבד', 'רק בחתימת עורך דין'], 'c': 1, 'e': 'נכון. כך קובע ס׳ 14(א)–(ב). בטיפולים שבתוספת (ניתוחים ועוד) נדרש מסמך שכולל את תמצית ההסבר.'}, {'q': 'מה הוא מבחן "ההטיה הנשנית" שנקבע בדנ״א מלול?', 'o': ['כלל שקובע שכל רופא שהתרשל פעמיים חב בפיצוי מלא', 'תנאי לפיצוי הסתברותי בהגברת סיכון: מזיק שיוצר סיכון חוזר ומשותף לקבוצת ניזוקים, באופן שמאזן ההסתברויות מטה עקבית לטובת צד אחד', 'מבחן לקביעת שיעור אשם תורם', 'מבחן לזיהוי משוא פנים של שופט'], 'c': 1, 'e': 'נכון. ארבעה יסודות: מזיק, קבוצת ניזוקים, סיכון חוזר ומשותף והטיה עקבית בהחלת כלל מאזן ההסתברויות.'}, {'q': 'אבחון רשלני הפחית בכמה אחוזים בודדים את סיכויי ההחלמה של מטופל שסיכוייו היו נמוכים מאוד מלכתחילה. מה עמדת הפסיקה בשאלת פיצוי על אובדן סיכוי זניח?', 'o': ['אובדן סיכוי מפוצה רק אם עלה על 50%', 'הפסיקה קבעה שזניח פירושו מתחת ל־30%', 'בע״א דנינו הציע השופט עמית שלא לפצות על אובדן זניח, והשאלה לא הוכרעה סופית', 'נקבעה הלכה מחייבת שתמיד יש לפצות, גם על שיעור זניח'], 'c': 2, 'e': 'נכון. השופט עמית הציע כלל של אי־פיצוי בשיעור זניח. שאר השופטים לא הכריעו, והבקשה לדיון נוסף נדחתה.'}, {'q': 'מטופלת גילתה ב־2026 נזק שנגרם לה בניתוח ב־2014, ולא יכלה לגלותו קודם. האם תביעתה התיישנה?', 'o': ['כן, כי לפי ס׳ 89(2) תביעה על נזק שנתגלה מאוחר מתיישנת בכל מקרה כעבור עשר שנים מיום אירוע הנזק', 'כן, כי ההתיישנות היא שנה אחת מיום הניתוח', 'לא, כי אין התיישנות ברשלנות רפואית', 'לא, כי ההתיישנות מתחילה תמיד ביום הגילוי'], 'c': 0, 'e': 'נכון. ס׳ 89(2) מאפשר להתחיל את המרוץ ביום הגילוי, "אלא שבמקרה אחרון זה תתיישן התובענה אם לא הוגשה תוך עשר שנים מיום אירוע הנזק". כאן חלפו 12 שנים.'}, {'q': 'קופת חולים לא קבעה נוהל להעברת תוצאות בדיקות חריגות לרופא המטפל, ותוצאה חמורה "נפלה בין הכיסאות". על איזה בסיס עיקרי תחוב הקופה?', 'o': ['באחריות ישירה בשל כשל מערכתי וארגוני, ואפשר גם באחריות שילוחית', 'אין אחריות כשאי אפשר להצביע על רופא אשם', 'רק באחריות חוזית כלפי המבוטח', 'רק באחריות שילוחית לרופא מסוים'], 'c': 0, 'e': 'נכון. מוסד רפואי חב ישירות על כשלים מערכתיים כמו היעדר נהלים, מחסור בכוח אדם ותקשורת לקויה.'}, {'q': 'בית משפט מחוזי קבע שהגברת סיכון על ידי הצוות הרפואי מעבירה לנתבעים את נטל ההוכחה בשאלת הקשר הסיבתי. האם קביעה זו תואמת את ההלכה?', 'o': ['כן, אבל רק בניתוחים קיסריים', 'כן, הגברת סיכון תמיד מעבירה את הנטל', 'לא, כי בכל מקרה של הגברת סיכון התביעה נדחית', 'לא, הגברת סיכון כשלעצמה אינה מעבירה את נטל ההוכחה, ותובע שאינו עומד במאזן ההסתברויות זכאי לכל היותר לפיצוי הסתברותי בתנאים שנקבעו'], 'c': 3, 'e': 'נכון. הקשר הסיבתי עדיין צריך הוכחה. פיצוי לפי הסתברות אפשרי רק לפי הלכות פאתח ומלול ותנאיהן.'}, {'q': 'לפי איזה סטנדרט נמדד רופא?', 'o': ['אדם מן הישוב', 'רופא סביר וכשיר', 'המטופל', 'המנהל'], 'c': 1, 'e': 'פרקטיקה רפואית מקובלת.'}, {'q': 'הסכמה מדעת מעוגנת ב:', 'o': ["ס' 35 לפקודה", "ס' 13 לחוק זכויות החולה", "ס' 64", "ס' 76"], 'c': 1, 'e': 'חובת מסירת מידע וקבלת הסכמה.'}, {'q': 'מה חידשה הלכת דעקה?', 'o': ['ביטלה רשלנות', 'פגיעה באוטונומיה כראש נזק עצמאי', 'אחריות מוחלטת', 'ייחוד עילה'], 'c': 1, 'e': 'נזק לא-ממוני נפרד.'}, {'q': 'הסכמה מדעת נמדדת לפי צרכי:', 'o': ['הרופא', 'המטופל הסביר', 'המנהל', 'המבטח'], 'c': 1, 'e': 'מידע שמטופל סביר זקוק לו.'}, {'q': 'אי-קבלת הסכמה מדעת עשויה להיתבע גם כ:', 'o': ['חוזה', "הפרת חובה חקוקה (ס' 13)", 'גזל', 'מטרד'], 'c': 1, 'e': "דרך ס' 63 + ס' 13."}]
MAR=[]
